import Foundation
import VRCCore

/// Publishes destination feeds, and refuses in every case where it is not
/// certain it should.
///
/// Four gates stand between an approved decision and a served feed, and all
/// four have to agree:
///
///   1. `OutboundSyncGate.isEnabled` in the code.
///   2. `VRC_OUTBOUND_ENABLED` in the environment.
///   3. `ExportPolicy` re-derives eligibility from the classification rather
///      than trusting any flag on the decision.
///   4. The generated bytes are verified by parsing them back before anything
///      is uploaded.
///
/// Partial success is reported as partial. An upload that lands but whose
/// cache invalidation fails leaves new bytes at the origin that nobody is
/// being served, and calling that "synchronised" would be a lie.
public struct PublishHandler {
    public enum Stage: String, Sendable {
        case refused
        case prepared
        case uploaded
        case purged
        case failed
    }

    public struct Outcome: Sendable {
        public var stage: Stage
        public var destination: String
        public var entryCount: Int
        public var nightCount: Int
        public var bodySHA256: String
        public var revision: Int
        public var detail: String
        public var isRemoteSynchronised: Bool { false }
    }

    let context: ServiceContext
    let objects: ObjectStore
    let invalidator: CacheInvalidator

    public init(context: ServiceContext, objects: ObjectStore, invalidator: CacheInvalidator) {
        self.context = context
        self.objects = objects
        self.invalidator = invalidator
    }

    public func publish(
        destination: RentalPlatform,
        propertyID: Int64,
        propertyName: String,
        sourceEvents: [ClassifiedEvent],
        decisions: [AvailabilityDecision],
        objectKey: String,
        revision: Int,
        scope: FeedPublicationScope = .approvedManualBlocksOnly,
        now: Date = Date()
    ) throws -> Outcome {

        func refuse(_ why: String) -> Outcome {
            Outcome(stage: .refused, destination: destination.rawValue, entryCount: 0,
                    nightCount: 0, bodySHA256: "", revision: revision, detail: why)
        }

        // Gate 1 and 2.
        guard OutboundSyncGate.isEnabled else {
            return refuse("OutboundSyncGate.isEnabled is false in the code")
        }
        guard context.outboundEnabled else {
            return refuse("VRC_OUTBOUND_ENABLED is not true in this function's environment")
        }

        // Only approved decisions, and only for this destination. A decision
        // in any other state is not a mandate to publish.
        let eligible = decisions.filter {
            $0.destination == destination && $0.status == .approved
        }
        guard !eligible.isEmpty else {
            return refuse("no approved decisions for \(destination.displayName)")
        }

        let feed = CalendarFeedGenerator().generate(
            destination: destination, propertyID: propertyID, propertyName: propertyName,
            sourceEvents: sourceEvents, decisions: eligible,
            scope: scope, revision: revision, now: now)

        // Gate 3, independently of the generator: nothing that fails
        // `describesGenuineUnavailability` may appear. The generator already
        // excludes them; this re-derives it from the classification so a bug
        // in one does not become a published block.
        let forbidden = sourceEvents.filter {
            !$0.classification.kind.describesGenuineUnavailability
        }
        let forbiddenUIDs = Set(forbidden.map {
            CalendarFeedGenerator().stableUID(
                forSourceKey: $0.event.eventKey, destination: destination)
        })
        let leaked = feed.included.filter { forbiddenUIDs.contains($0.uid) }
        guard leaked.isEmpty else {
            return refuse(
                "refusing to publish: \(leaked.count) entr(ies) derive from events that are "
                + "not genuine unavailability (cancellation penalties, platform restrictions, "
                + "provisional holds or unknown blocks)")
        }

        let body = CalendarFeedGenerator().makeICS(feed)

        // Gate 4: parse the bytes back. A feed that cannot be read is worse
        // than no feed, and a platform would simply keep the old one.
        let reparsed: ICalParseResult
        do {
            reparsed = try ICalParser.parse(body)
        } catch {
            return Outcome(stage: .failed, destination: destination.rawValue, entryCount: 0,
                           nightCount: 0, bodySHA256: "", revision: revision,
                           detail: "the generated feed did not parse back: \(error)")
        }
        guard reparsed.events.count == feed.included.count else {
            return Outcome(stage: .failed, destination: destination.rawValue,
                           entryCount: feed.included.count, nightCount: feed.includedNights,
                           bodySHA256: "", revision: revision,
                           detail: "generated \(feed.included.count) entries but the feed "
                               + "parsed back as \(reparsed.events.count)")
        }

        let digest = EventKey.sha256(body)
        var outcome = Outcome(
            stage: .prepared, destination: destination.rawValue,
            entryCount: feed.included.count, nightCount: feed.includedNights,
            bodySHA256: digest, revision: revision, detail: "verified, not yet uploaded")

        // Last-known-good is written FIRST, under a key that includes the
        // digest, so recovery never depends on the publish that follows
        // succeeding.
        try objects.put(key: "last-known-good/\(destination.rawValue)/\(digest).ics",
                        body: Data(body.utf8), contentType: "text/calendar")

        do {
            try objects.put(key: objectKey, body: Data(body.utf8), contentType: "text/calendar")
            outcome.stage = .uploaded
            outcome.detail = "uploaded; cache not yet purged"
        } catch {
            outcome.stage = .failed
            outcome.detail = "upload failed, the previous feed is still being served: \(error)"
            return outcome
        }

        do {
            try invalidator.invalidate(paths: ["/\(objectKey)"])
            outcome.stage = .purged
            outcome.detail = "published and cache purged — awaiting the platform's own refresh"
        } catch {
            // Deliberately NOT .purged and deliberately not an error: the
            // bytes are at the origin, readers may still get the old ones, and
            // the only honest description of that is "uploaded".
            outcome.stage = .uploaded
            outcome.detail = "uploaded, but the cache purge failed, so readers may still be "
                + "served the previous feed: \(error)"
        }
        return outcome
    }
}
